import java.nio.file.*;
import java.util.*;
/** Opt-in, isolated development client. No account, world, or production profile is used. */
public final class ClientSmoke {
 private static final boolean ITEM_FOCUS=Boolean.getBoolean("zianmobs.itemFocus");
 private static final boolean SHADOW_FOCUS=Boolean.getBoolean("zianmobs.shadowFocus");
 private static final int LIMIT=SHADOW_FOCUS?21:ITEM_FOCUS?3:54;
 private static final int START=Integer.getInteger("zianmobs.clientSmokeStart",0);
 private static int ticks,stage=-1;private static final List<Item> items=new ArrayList<>();
 public static void register(){StageEditorSmoke.register();ConsolidationClientSmoke.register();if(Boolean.getBoolean("zianmobs.clientSmoke"))net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(ClientSmoke::tick);}
 private static void require(boolean b,String message){if(!b)throw new IllegalStateException(message);}
 private static void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.getOverlay()!=null||mc.screen==null)return;try{
  if(stage<0){Class.forName("net.minecraft.client.multiplayer.ClientPacketListener");require(mc.gameDirectory.toPath().toAbsolutePath().normalize().toString().contains("mobs-client-smoke"),"Client smoke requires isolated profile");Gear.ITEMS.values().forEach(i->items.add(i.get()));SpawnEggs.EGGS.forEach(i->items.add(i.get()));com.ianblk.zianmobs.CompanionContent.ARMOR.values().forEach(i->items.add(i.get()));com.ianblk.zianmobs.CompanionContent.EXTRAS.values().forEach(i->items.add(i.get()));com.ianblk.zianmobs.CompanionUpgrades.ITEMS.values().forEach(i->items.add(i.get()));for(var item:items){var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item);var model=mc.getModelManager().getModel(ModelResourceLocation.inventory(id));require(model!=mc.getModelManager().getMissingModel(),"Missing item model "+id);{var quads=new ArrayList<>(model.getQuads(null,null,RandomSource.create(0)));for(var side:Direction.values())quads.addAll(model.getQuads(null,side,RandomSource.create(0)));require(!quads.isEmpty(),"Empty item geometry "+id);for(var q:quads)require(!q.getSprite().contents().name().getPath().equals("missingno"),"Missing atlas sprite "+id);}}TitanVisualSmoke.check(mc.getModelManager().getModel(ModelResourceLocation.inventory(ResourceLocation.fromNamespaceAndPath("zianmobs","titan_gauntlet"))),false);stage=START;ticks=0;if(stage==0&&!SHADOW_FOCUS)mc.setScreen(new Catalog(0));else openStage(mc);}
  if(SHADOW_FOCUS&&stage<3&&(ticks==5||ticks==11||ticks==17||ticks==23||ticks==29))ShadowAnimationProbe.sample();
  if(++ticks<35)return;if(SHADOW_FOCUS&&stage==2)ShadowAnimationProbe.verify();ticks=0;if(stage>=3&&!SHADOW_FOCUS)require((int)mc.getWindow().getGuiScale()==2+(stage-3)%3,"Requested GUI scale was clamped by the window");
  Screenshot.grab(mc.gameDirectory,"smoke-"+stage+".png",mc.getMainRenderTarget(),c->ZianMobs.LOGGER.info("Client smoke screenshot: {}",c.getString()));
  stage++;if(stage<LIMIT)openStage(mc);else{Files.writeString(mc.gameDirectory.toPath().resolve("client-smoke-result.txt"),(SHADOW_FOCUS?"PASS: 14 Shadow materials baked with resolved sprites; animated frame uploads verified; material catalog and upgrade stats at GUI scales 2, 3, 4; actual material selector and response router retain material and tab after success and rejection, refresh stats and token, and do not show false unsaved prompts.\n":ITEM_FOCUS?"PASS: 72 baked inventory models with nonempty geometry and resolved sprites; three equipment inventory pages, including native Titan sword and gauntlet.\n":"PASS: "+items.size()+" baked inventory models; "+(LIMIT-START)+" screenshots in this pass including owned/all filters, collection pagination/search, companions ready/dead/locked, companion settings and access at GUI scales 2, 3, 4; actual server dashboard, mob/zone/NPC tabs and read-only gear catalog plus scythe, staff, Master Sword and Hylian Shield ability cards rendered at GUI scales 2, 3, 4; tab edits retained and unsaved-close confirmation verified.\n"));ZianMobs.LOGGER.info("ZIAN-MOBS-CLIENT-SMOKE PASS");mc.stop();}

 }catch(Throwable e){ZianMobs.LOGGER.error("ZIAN-MOBS-CLIENT-SMOKE FAIL",e);try{Files.writeString(mc.gameDirectory.toPath().resolve("client-smoke-result.txt"),"FAIL: "+e);}catch(Exception ignored){}mc.stop();}}
 private static void press(MobsScreen screen,String text){var button=screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals(text)).map(c->(net.minecraft.client.gui.components.Button)c).findFirst().orElseThrow(()->new IllegalStateException("Missing tab "+text));if(button.active)button.onPress();}
 private static void openStage(Minecraft mc)throws Exception{
  if(SHADOW_FOCUS){mc.options.guiScale().set(2+stage%3);mc.resizeDisplay();if(stage>=18){UpgradeSelectionSmoke.run(mc,new String[]{"Básico","Combate","Habilidades"}[stage-18]);}else if(stage<3){mc.setScreen(new ShadowCatalog());}else if(stage>=15){var data=JsonParser.parseString(Files.readString(mc.gameDirectory.toPath().resolve("fixtures/companions_locked.json"))).getAsJsonObject();var screen=new CompanionScreen(data);mc.setScreen(screen);require(screen.children().stream().noneMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Sleepy")),"Default owned filter shows locked companion");var toggle=screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Ver todos")).map(c->(net.minecraft.client.gui.components.Button)c).findFirst().orElseThrow();toggle.onPress();require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Sleepy")),"View all does not reveal locked companions");}else if(stage>=12){var data=JsonParser.parseString(Files.readString(mc.gameDirectory.toPath().resolve("fixtures/companions_ready.json"))).getAsJsonObject();mc.setScreen(new CompanionScreen(data));}else{var data=JsonParser.parseString(Files.readString(mc.gameDirectory.toPath().resolve("fixtures/companion_upgrades.json"))).getAsJsonObject();var screen=new MobsScreen(data);mc.setScreen(screen);press(screen,stage<6?"Combate":stage<9?"Habilidades":"Básico");}return;}

  if(stage<3){mc.setScreen(new Catalog(stage));return;}
  mc.options.guiScale().set(2+(stage-3)%3);mc.resizeDisplay();String name=stage<6?"home":stage<9?"mob":stage<12?"zone":stage<15?"npc":"item";
  if(stage>=18&&stage<30)name=new String[]{"carnivoret_weapon_set_scythe","valentines_animated_weapon_and_tool_set_v1_staff","toffy_master_sword","toffy_hylian_shield"}[(stage-18)/3];
  if(stage>=51){var data=JsonParser.parseString(Files.readString(mc.gameDirectory.toPath().resolve("fixtures/companions_locked.json"))).getAsJsonObject();var screen=new CompanionScreen(data);mc.setScreen(screen);require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Ver todos")),"Owned filter was not selected by default");require(screen.children().stream().noneMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Sleepy")),"Locked companion leaked into owned filter");return;}

  if(stage>=45){var fixture=mc.gameDirectory.toPath().resolve("fixtures/companions_ready.json");var data=JsonParser.parseString(Files.readString(fixture)).getAsJsonObject();var screen=new CompanionScreen(data);mc.setScreen(screen);if(stage<48){for(int i=0;i<4;i++){var button=screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Siguiente")).map(c->(net.minecraft.client.gui.components.Button)c).findFirst().orElseThrow();require(button.active,"Collection pagination ended early");button.onPress();}require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Marea")),"Final companion page is missing");}else{var search=screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.EditBox).map(c->(net.minecraft.client.gui.components.EditBox)c).findFirst().orElseThrow();search.setValue("N");for(char letter:new char[]{'i','e','v','e'})screen.charTyped(letter,0);require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.EditBox box&&box.getValue().equals("Nieve")),"Search loses focus while typing");require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Nieve")),"Search did not find snow companion");}return;}
  if(stage>=30)name=new String[]{"companions_ready","companions_dead","companions_locked","companion_settings","companion_access"}[(stage-30)/3];
  var fixture=mc.gameDirectory.toPath().resolve("fixtures/"+name+".json");require(Files.isRegularFile(fixture),"Run server smoke first to generate real admin fixtures");var data=JsonParser.parseString(Files.readString(fixture)).getAsJsonObject();if(stage>=30&&stage<39){mc.setScreen(new CompanionScreen(data));return;}var screen=new MobsScreen(data);mc.setScreen(screen);
  if(stage==6){var box=screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.EditBox e&&e.getValue().equals("Guardián abisal")).map(c->(net.minecraft.client.gui.components.EditBox)c).findFirst().orElseThrow();box.setValue("Guardián abisal · prueba");press(screen,"Equipo");press(screen,"Básico");require(screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.EditBox e&&e.getValue().equals("Guardián abisal · prueba")),"Tab navigation lost the edited name");screen.onClose();require(mc.screen instanceof ManagerConfirmScreen,"Unsaved edit closed without confirmation");mc.setScreen(screen);}
  if(stage>=6&&stage<15){String[] tab=stage<9?new String[]{"Básico","Equipo","Avanzado"}:stage<12?new String[]{"Tamaño","Puntos","Avanzado"}:new String[]{"Básico","Combate","Habilidades"};press(screen,tab[(stage-3)%3]);}
 }
 private static final class ShadowCatalog extends ManagerThemedScreen {
  ShadowCatalog(){super(Component.translatableWithFallback("ui.zianmobs.2735c00affd0", "Materiales del Vínculo · revisión local"));}
  @Override protected void init(){fitViewport(620,370);}
  @Override protected void renderCanvas(GuiGraphics g,int mx,int my,float dt){int x=(width-600)/2,y=(height-350)/2;panel(g,x,y,600,350);int n=0;for(var m:com.ianblk.zianmobs.CompanionUpgrades.CATALOG){int col=n/2,row=n%2;var stack=com.ianblk.zianmobs.CompanionUpgrades.ITEMS.get(m.id()).get().getDefaultInstance();int px=x+10+col*84,py=y+55+row*128;g.pose().pushPose();g.pose().translate(px+10,py,0);g.pose().scale(3,3,1);g.renderItem(stack,0,0);g.pose().popPose();g.drawString(font,font.plainSubstrByWidth(m.name(),78),px,py+55,0xFFE4D8B5);g.drawString(font,row==0?"Estático":"Animado",px,py+68,0xFF99D6E8);n++;}renderWidgets(g,mx,my,dt);}
 }
 private static final class Catalog extends ManagerThemedScreen{
  private final int page;Catalog(int p){super(Component.literal("Zian Mobs · Catálogo "+(p+1)+" / 3"));page=p;}
  @Override protected void init(){fitViewport(600,360);}
  @Override protected void renderCanvas(GuiGraphics g,int mx,int my,float dt){int left=(width-600)/2,top=(height-360)/2;panel(g,left,top,600,360);for(int i=page*28;i<Math.min(items.size(),(page+1)*28);i++){int n=i%28,x=left+8+(n%7)*84,y=top+42+(n/7)*78;var stack=items.get(i).getDefaultInstance();g.pose().pushPose();g.pose().translate(x+22,y,0);g.pose().scale(2,2,1);g.renderItem(stack,0,0);g.pose().popPose();g.drawString(font,font.plainSubstrByWidth(stack.getHoverName().getString(),79),x,y+40,0xFFE4D8B5);}if(page==2){g.renderTooltip(font,Gear.ITEMS.get("toffy_rupee").get().getDefaultInstance(),left+24,top+70);g.renderTooltip(font,Gear.ITEMS.get("carnivoret_weapon_set_sword").get().getDefaultInstance(),left+300,top+180);}renderWidgets(g,mx,my,dt);}
 }
}
